document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.homeView){if(b.dataset.homeView==='reports'&&homeData)report=homeData.range;await changeView(b.dataset.homeView);if(b.dataset.homeView==='orders'){$('order-search').value='';$('order-status').value='';if($('order-dates')){$('order-dates').elements.from.value='';$('order-dates').elements.to.value='';}$('order-list').innerHTML=orderTable();}if(b.dataset.homeView==='ads'){toolsGroup.open=true;}}if(b.hasAttribute('data-home-refresh')){homeRetryCount=0;homeReports.clear();await loadHome(true);}if(b.dataset.homePeriod){const end=today();homeRange={from:b.dataset.homePeriod==='day'?end:b.dataset.homePeriod==='week'?new Date(Date.parse(end+'T12:00:00Z')-6*86400000).toISOString().slice(0,10):end.slice(0,7)+'-01',to:end};await loadHome(true);}if(b.dataset.chartMetric){homeMetric=b.dataset.chartMetric;drawHome();document.querySelector(`[data-chart-metric="${homeMetric}"]`)?.focus({preventScroll:true});}if(b.hasAttribute('data-chart-point')){homeSelected=Number(b.dataset.chartPoint);drawHome();document.querySelector(`[data-chart-point="${homeSelected}"]`)?.focus({preventScroll:true});}if(b.hasAttribute('data-ranking')){const name=Object.entries(homeData.range.topProducts).sort((a,b)=>b[1]-a[1])[Number(b.dataset.ranking)]?.[0],resource=allResources().find(r=>r.product===name);await changeView('inventory');const f=$('inventory-filter').elements;f.stage.value='PACKAGED';if(resource){f.family.value=resource.family;f.grind.value=resource.grind;f.grams.value=resource.grams;}$('inventory-rows').innerHTML=inventoryRows();}if(b.dataset.quickOffer){const row=b.closest('.cv-line');row.querySelector('[data-offer]').value=b.dataset.quickOffer;updateLine(row);dirty=true;persistDraft();}if(b.hasAttribute('data-apply-customer')){const id=$('existing-customer').value,c=(snapshot.reports.customers||[]).find(c=>c.id===id);if(!c){notice('Selecciona un cliente existente.');return;}const values=CVVisual.customerContact(c,snapshot.sales);for(const [key,value]of Object.entries(values)){const name=key==='name'?'customer':key;if($('sale-form').elements[name])$('sale-form').elements[name].value=value;}dirty=true;persistDraft();notice('Datos del cliente recuperados en el borrador. Revisa la dirección antes de registrar.');}}
 catch(error){notice(explain(error));}});
