store.transact(s=>{if(!homeData&&s.uxHome5a2)homeData=s.uxHome5a2;}).then(()=>{if(snapshot)render();});
const baseAdsRefinement=renderAdsDemo;renderAdsDemo=function(){baseAdsRefinement();if(!$('ads-filter'))return;const fields=formdata($('ads-filter')),rows=demoAds.filter(r=>r.day>=fields.from&&r.day<=fields.to&&(!fields.campaign||r.campaign===fields.campaign)&&(!fields.ad||r.ad===fields.ad)),last=rows.at(-1);if(!last)return;const cardsHTML=`<p class="data-caption">Tarjetas del último día visible: ${esc(last.day)} · exclusivamente cifras de demostración.</p><div class="home-kpis ads-kpis">${metricCard('Inversión diaria · DEMO',money(last.spendCents),'No es gasto real del negocio','ads','ads')}${metricCard('Impresiones · DEMO',last.impressions,'Último día visible','reports','ads')}${metricCard('Alcance diario · DEMO',last.reach,'No sumar como alcance único del período','customers','ads')}${metricCard('Conversaciones · DEMO',last.conversations,'No equivalen a ventas confirmadas','orders','ads')}</div><article class="card"><div class="panel-head"><div><h3>Inversión publicitaria diaria</h3><p>Gráfico de demostración · no alimenta el resultado comercial</p></div><span class="tag demo">Datos ficticios</span></div>${rows.map(r=>`<div class="ad-chart-bar"><span>${esc(r.day)}</span><i style="width:${r.spendCents/Math.max(...rows.map(x=>x.spendCents),1)*55}%"></i><b>${money(r.spendCents)}</b></div>`).join('')}<p class="cv-help">CTR, CPC y CPM aparecen en la tabla inferior. ROAS: sin atribución verificable. Actualización de ejemplo: 15/10/2026, 12:00 (Lima).</p></article>`;$('ads-demo-results').insertAdjacentHTML('beforebegin',cardsHTML);};
function filterExistingCustomers(query){const select=$('existing-customer');if(!select)return;const selected=select.value,needle=query.toLowerCase().trim();select.innerHTML=option('','Selecciona un cliente del laboratorio')+(snapshot.reports.customers||[]).filter(c=>`${c.name} ${c.phone}`.toLowerCase().includes(needle)).map(c=>option(c.id,c.name+(c.phone?' · •••'+c.phone.slice(-3):''))).join('');if([...select.options].some(o=>o.value===selected))select.value=selected;}
const previousEnhanceSales=enhanceSales;enhanceSales=function(){previousEnhanceSales();const box=$('sale-form')?.querySelector('.quick-customer');if(box&&!$('customer-lookup')){box.insertAdjacentHTML('afterbegin','<label>Buscar cliente<input id="customer-lookup" type="search" placeholder="Nombre o teléfono ficticio" autocomplete="off"></label>');}};
document.addEventListener('input',e=>{if(e.target.id==='customer-lookup')filterExistingCustomers(e.target.value);});
const lookupEnhance=enhanceSales;enhanceSales=function(){lookupEnhance();const box=$('sale-form')?.querySelector('.quick-customer');if(box&&!box.closest('.customer-lookup-panel')){const detail=document.createElement('details');detail.className='customer-lookup-panel';detail.innerHTML='<summary>Recuperar datos de un cliente existente</summary>';box.before(detail);detail.append(box);}};
document.addEventListener('change',e=>{if(e.target.id==='existing-customer'&&e.target.value)document.querySelector('[data-apply-customer]')?.click();});
document.addEventListener('keydown',e=>{if(e.target.id==='customer-lookup'&&e.key==='Enter'){e.preventDefault();const select=$('existing-customer');if(select.options.length===2){select.value=select.options[1].value;document.querySelector('[data-apply-customer]')?.click();}}});
const mobileNewOrderEnhance=enhanceSales;enhanceSales=function(){mobileNewOrderEnhance();const actions=$('sales')?.querySelector('.page-actions');if(actions&&!actions.querySelector('.mobile-new-order'))actions.insertAdjacentHTML('beforeend','<button type="button" class="btn secondary mobile-new-order" data-new-order>Nuevo pedido</button>');};
function connectionTone(){const el=$('connection'),text=el.textContent||'';el.dataset.tone=/Pendiente|Última copia|Conectando/.test(text)?'warning':/Sin confirmación/.test(text)?'error':'positive';}new MutationObserver(connectionTone).observe($('connection'),{childList:true,characterData:true,subtree:true});connectionTone();
let draftStatusObserver=null;const statusEnhance=enhanceSales;enhanceSales=function(){statusEnhance();if(draftStatusObserver)draftStatusObserver.disconnect();if($('draft-state')){draftStatusObserver=new MutationObserver(updateMobileStatus);draftStatusObserver.observe($('draft-state'),{childList:true,characterData:true,subtree:true});updateMobileStatus();}};
const contextualChangeView=changeView;changeView=async function(name){await contextualChangeView(name);notice(/^\d+/.test($('pending').textContent||'')?'Hay operaciones pendientes de confirmación. Se conservan en la cola.':'Laboratorio local · datos ficticios. Consulta el estado de cada pedido.');};
document.addEventListener('click',e=>{if(e.target.closest('[data-new-order]'))notice(/^\d+/.test($('pending').textContent||'')?'Nuevo borrador. Las operaciones anteriores pendientes siguen en la cola.':'Nuevo borrador · todavía no enviado al servidor.');});
